    return np.stack((result.real, result.imag), axis=0)

def _independent(value):
    return np.array(value, copy=True)
assert np.allclose(_checked_numeric(hard_spin_color_density(_independent(C), [[0.55, 0.04], [0.04, 0.45]]), (2, 2, 3, 3)), target)

