import numpy as np
def _case_accuracy(value, reference):
    try:
        actual=np.asarray(value); expected=np.asarray(reference)
        if actual.shape!=expected.shape or actual.dtype.kind not in 'iuf': return False
        if not np.all(np.isfinite(actual)) or not np.all(np.isfinite(expected)): return 0.0
        budget=np.maximum(1e-7,2*np.abs(np.spacing(expected.astype(np.float64))))
        return float(np.all(np.abs(actual-expected)<=budget))
    except (TypeError,ValueError,OverflowError): return 0.0
def rejects_value_error(fn,*args):
    try: fn(*args)
    except ValueError: return 1.0
    except Exception: return 0.0
    return 0.0
assert np.allclose(rejects_value_error(finite_veto_tensors,[1.3],[.2,3.],[-.4,.6],[-1.,1.]), target)

